ee:message.ee:set-payload:
%dw 2.0
import toLocalDateTimeOrNull from dw::util::Coercions
output application/java

var currentRecord =
    if (payload is Array)
        payload[0] default {}
    else
        payload

var row = {
    SKU:
        trim((currentRecord.SKU default "") as String),

    StoreId:
        trim((currentRecord.StoreId default "") as String),

    Type:
        trim((currentRecord.Type default "") as String),

    Quantity:
        trim((currentRecord.Quantity default "") as String),

    Timestamp:
        trim((currentRecord.Timestamp default "") as String)
}

var quantityIsWholeNumber =
    !isEmpty(row.Quantity)
    and (row.Quantity matches /^\d+$/)

var timestampValue =
    if (isEmpty(row.Timestamp))
        null
    else
        toLocalDateTimeOrNull(
            row.Timestamp,
            [
                {
                    format: "M/d/uuuu H:mm"
                },
                {
                    format: "MM/dd/uuuu HH:mm"
                }
            ]
        )

var timestampIsValid =
    !isEmpty(row.Timestamp)
    and timestampValue != null

var validationReasons =
    []
    ++ (
        if (isEmpty(row.SKU))
            ["SKU is required"]
        else
            []
    )
    ++ (
        if (isEmpty(row.StoreId))
            ["StoreId is required"]
        else
            []
    )
    ++ (
        if (isEmpty(row.Type))
            ["Type is required"]
        else
            []
    )
    ++ (
        if (
            !isEmpty(row.Type)
            and !(["Standard", "Backorder"] contains row.Type)
        )
            ["Type must be Standard or Backorder"]
        else
            []
    )
    ++ (
        if (isEmpty(row.Quantity))
            ["Quantity is required"]
        else if (!quantityIsWholeNumber)
            ["Quantity must be a non-negative whole number"]
        else
            []
    )
    ++ (
        if (isEmpty(row.Timestamp))
            ["Timestamp is required"]
        else if (!timestampIsValid)
            ["Timestamp must be a valid date in M/d/yyyy H:mm format"]
        else
            []
    )

---
{
    data: {
        SKU: row.SKU,
        StoreId: row.StoreId,
        Type: row.Type,
        Quantity:
            if (quantityIsWholeNumber)
                row.Quantity as Number
            else
                row.Quantity,
        Timestamp: row.Timestamp
    },
    validation: {
        isValid: isEmpty(validationReasons),
        reasons: validationReasons
    }
}

%dw 2.0
output application/java

var validRows =
    payload map ((record) -> record.data)

---
(validRows groupBy ((record) -> record.StoreId))
    pluck ((records, storeId) -> {
        storeId: storeId,
        records: records
    })
